namespace SESRS.Models;

/// <summary>
/// Personal information an administrator records when a student registers in person.
/// The official student number and the login are generated by the system, never typed in.
/// </summary>
public sealed record NewStudentRequest(
    string FirstName,
    string? MiddleName,
    string LastName,
    string Gender,
    DateTime BirthDate,
    string Email,
    string Phone,
    string Address,
    int ProgramId,
    int YearLevel);

/// <summary>Login details handed to a student. The password is shown once and never stored in plain text.</summary>
public sealed record IssuedCredentials(
    string FullName,
    string Username,
    string TemporaryPassword);

public sealed record CreatedStudentAccount(
    int StudentId,
    string StudentNumber,
    IssuedCredentials Credentials);
